<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><?php $errors=session('errors')??[]; ?><section class="workspace"><div class="container"><div class="form-shell"><a class="back-link" href="<?= site_url('users') ?>">Back to users</a><h1><?= esc($title) ?></h1><p>Use a unique username and assign only the access level required.</p><form action="<?= esc($action,'attr') ?>" method="post" enctype="multipart/form-data" novalidate><?= csrf_field() ?><div class="row g-3"><div class="col-md-6"><label class="form-label" for="username">Username <span aria-hidden="true">*</span></label><input class="form-control <?= isset($errors['username'])?'is-invalid':'' ?>" id="username" name="username" maxlength="50" autocomplete="username" value="<?= esc(old('username',$user['username']??'')) ?>" required><?php if(isset($errors['username'])): ?><div class="invalid-feedback"><?= esc($errors['username']) ?></div><?php endif; ?></div><div class="col-md-6"><label class="form-label" for="full_name">Full name <span aria-hidden="true">*</span></label><input class="form-control <?= isset($errors['full_name'])?'is-invalid':'' ?>" id="full_name" name="full_name" maxlength="100" value="<?= esc(old('full_name',$user['full_name']??'')) ?>" required><?php if(isset($errors['full_name'])): ?><div class="invalid-feedback"><?= esc($errors['full_name']) ?></div><?php endif; ?></div><div class="col-md-6"><label class="form-label" for="role">Role <span aria-hidden="true">*</span></label><select class="form-select <?= isset($errors['role'])?'is-invalid':'' ?>" id="role" name="role" required><?php $selected=old('role',$user['role']??'cashier');foreach(['admin'=>'Administrator','manager'=>'Manager','cashier'=>'Cashier'] as $value=>$label): ?><option value="<?= $value ?>" <?= $selected===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select><?php if(isset($errors['role'])): ?><div class="invalid-feedback"><?= esc($errors['role']) ?></div><?php endif; ?></div><div class="col-md-6"><label class="form-label" for="password">Password <?= $user?'':'<span aria-hidden="true">*</span>' ?></label><input class="form-control <?= isset($errors['password'])?'is-invalid':'' ?>" id="password" type="password" name="password" minlength="10" maxlength="255" autocomplete="new-password" <?= $user?'':'required' ?>><div class="form-text"><?= $user?'Leave blank to keep the current password.':'Use at least 10 characters.' ?></div><?php if(isset($errors['password'])): ?><div class="invalid-feedback"><?= esc($errors['password']) ?></div><?php endif; ?></div><div class="col-12"><label class="form-label" for="avatar">Avatar</label><div class="avatar-upload"><img id="avatarPreview" class="avatar avatar-lg" src="<?= !empty($user['avatar'])?base_url('uploads/avatars/'.rawurlencode($user['avatar'])):base_url('assets/avatar-placeholder.svg') ?>" alt="Current avatar"><div class="flex-grow-1"><input class="form-control <?= isset($errors['avatar'])?'is-invalid':'' ?>" id="avatar" type="file" name="avatar" accept="image/jpeg,image/png"><div class="form-text">JPG or PNG, up to 2 MB. The image will be cropped to a square.</div><?php if(isset($errors['avatar'])): ?><div class="invalid-feedback d-block"><?= esc($errors['avatar']) ?></div><?php endif; ?></div></div></div></div><div class="d-flex gap-2 mt-4"><button class="btn btn-accent" type="submit"><?= $user?'Save changes':'Create user' ?></button><a class="btn btn-light" href="<?= site_url('users') ?>">Cancel</a></div></form></div></div></section><?= $this->endSection() ?>
